import java.math.BigInteger;

public class PuissanceDeTrois {
    public static boolean isPuissanceDeTrois(int n) {
        // Vérification des cas de base
        if (n == 0 || n == 1 || n == -1) {
            return false;
        }

        // Conversion de n en BigInteger pour éviter les sous-typages
        BigInteger bigN = BigInteger.valueOf(n);

        // Calcul du logarithme en base 3 de n
        int log3N = bigN.intValueExact().bitLength() - 1;

        // Vérification de la congruence modulo 3
        return bigN.mod(BigInteger.valueOf(3)).equals(BigInteger.ZERO);
    }

    public static void main(String[] args) {
        int n = 27;
        boolean result = isPuissanceDeTrois(n);
        System.out.println(result); // Affiche true

        int m = 0;
        result = isPuissanceDeTrois(m);
        System.out.println(result); // Affiche false

        int p = -1;
        result = isPuissanceDeTrois(p);
        System.out.println(result); // Affiche false
    }
}
```

Explication:

1. Nous commençons en vérifiant les cas de base où n est égal à 0, 1 ou -1, car ils ne peuvent pas être des puissances de trois.
